import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

import 'accent.dart';
import 'theme.dart';

/// The OpenChroma logo: the ring mark and the wordmark, with the lit arc
/// and "Open" in the live accent.
class OcLogo extends StatelessWidget {
  const OcLogo({super.key, this.height = 22, this.wordmark = true});
  final double height;
  final bool wordmark;

  @override
  Widget build(BuildContext context) {
    final box = wordmark ? _full : _mark;
    return SizedBox(
      height: height,
      width: height * box.width / box.height,
      child: CustomPaint(
        painter: _LogoPainter(LiveAccent.of(context), box, wordmark),
      ),
    );
  }

  static const _mark = Rect.fromLTRB(51, 51, 437, 437);
  static const _full = Rect.fromLTRB(51, 51, 2187, 437);
}

/// The ring mark at [size] x [size] in [accent], as straight-alpha RGBA.
Future<Uint8List> renderLogoMark(Color accent, int size) async {
  final recorder = ui.PictureRecorder();
  _LogoPainter(
    accent,
    OcLogo._mark,
    false,
  ).paint(Canvas(recorder), Size.square(size.toDouble()));
  final image = await recorder.endRecording().toImage(size, size);
  try {
    final data = await image.toByteData(
      format: ui.ImageByteFormat.rawStraightRgba,
    );
    return data!.buffer.asUint8List();
  } finally {
    image.dispose();
  }
}

class _LogoPainter extends CustomPainter {
  _LogoPainter(this.accent, this.box, this.wordmark);
  final Color accent;
  final Rect box;
  final bool wordmark;

  static final _arc = parseSvgPath(_arcData);
  static final _open = parseSvgPath(_openData);
  static final _chroma = parseSvgPath(_chromaData);

  @override
  void paint(Canvas canvas, Size size) {
    final scale = size.height / box.height;
    canvas
      ..save()
      ..scale(scale)
      ..translate(-box.left, -box.top);
    final stroke = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 50
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    canvas
      ..drawCircle(const Offset(244, 244), 168, stroke..color = Oc.lineStrong)
      ..drawPath(_arc, stroke..color = accent)
      ..drawCircle(const Offset(244, 244), 66, Paint()..color = Oc.text);
    if (wordmark) {
      canvas
        ..drawPath(_open, Paint()..color = accent)
        ..drawPath(_chroma, Paint()..color = Oc.text);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(_LogoPainter old) =>
      old.accent != accent || old.wordmark != wordmark;
}

/// A path from SVG path data with absolute M, L, H, V, C and Z commands.
Path parseSvgPath(String data) {
  final tokens = RegExp(
    r'-?\d*\.?\d+(?:e[-+]?\d+)?|[a-z]',
    caseSensitive: false,
  ).allMatches(data).map((m) => m[0]!).toList();
  final path = Path();
  var i = 0, x = 0.0, y = 0.0;
  String? cmd;
  double next() => double.parse(tokens[i++]);
  while (i < tokens.length) {
    if (RegExp(r'^[A-Za-z]$').hasMatch(tokens[i])) cmd = tokens[i++];
    switch (cmd) {
      case 'M':
        x = next();
        y = next();
        path.moveTo(x, y);
        cmd = 'L';
      case 'L':
        x = next();
        y = next();
        path.lineTo(x, y);
      case 'H':
        x = next();
        path.lineTo(x, y);
      case 'V':
        y = next();
        path.lineTo(x, y);
      case 'C':
        final x1 = next(), y1 = next(), x2 = next(), y2 = next();
        x = next();
        y = next();
        path.cubicTo(x1, y1, x2, y2, x, y);
      case 'Z':
        path.close();
      default:
        throw FormatException('Unsupported SVG path command: $cmd');
    }
  }
  return path;
}

